{"schema_version":1,"status":"ok","source":{"id":1,"file":"src/work-context/binding.ts","start_byte":0,"end_byte":8192,"start_line":1,"end_line":241,"content_hash":"fcf9ce8fbbefdffcfdbd461a4c5b08e84f7a36220e99aee6dcdd64ad8ce3ca3f","content":"import { createHash, randomUUID } from "node:crypto";
